\vspace{-3mm}
\section{Proposed Variational Bayesian Inference Based Posterior PDF Characterization}\label{section_VBI}
\vspace{-3mm}
\subsection{Equivalent Transformation and Tractable Approximation}
\vspace{-3mm}
Firstly, we define \emph{pseudo angles} $\bm{\vartheta}=[\vartheta_1,...,\vartheta_M]^T$ with $\vartheta_m\overset{\Delta}{=}\frac{\pi}{2}\sin(\theta_m)$, which has a one-to-one mapping to $\theta_m$ since $\theta_m\in[-\frac{\pi}{2},\frac{\pi}{2})$ \cite{stoica2005spectral}. This yields $a_i(\vartheta_m)= e^{-\!j( N_t\!-\!2i+1 )\vartheta_m}$ and $b_i(\vartheta_m)=e^{-\!j( N_r\!-\!2j+1 )\vartheta_m}$ in the array steering vectors, thereby equivalently simplifying the observation model. The prior PDF of $\vartheta_m$ for each $s$-th stage is given by $\tilde{p}_{\Phi_m,s}(\vartheta_m)\!\!=\!\!p_{\Theta_m,s}(\mathrm{arcsin}(\frac{2\vartheta_m}{\pi}))\frac{2}{\sqrt{\pi^2-4\vartheta_m^2}}$. In the following, we focus on the posterior PDF with respect to $\bm{\vartheta}$. 
Secondly, note that the intractability of the posterior PDF mainly lies in the intractable conditional PDF $p(\bm{Y}^{(s)}|\bm{\vartheta})$. By noting that in each $s$-th stage, the prior PDFs for all previous $s$ stages are already available under our framework, we introduce an \emph{observation window} for each stage to enable a flexible trade-off between the complexity in obtaining the conditional PDF and sensing performance. Denote the observation window at the $s$-th stage as $\mathcal{W}_s=\{\rho(s),\rho(s)+1,...,s\}$ with $\rho(s)$ being the starting index of $\mathcal{W}_s$, and $\bm{Y}_{\mathcal{W}_s}=\{\bm{Y}_{\rho(s)},\bm{Y}_{\rho(s)+1},...,\bm{Y}_{s}\}$ as the collection of observations within this window. The posterior PDF can be then expressed as\footnote{Since we assume the targets' angles are posteriorly independent, (\ref{posterior2}) is an approximation of (\ref{posterior}) \cite{broderick2013streaming}. The approximation is exact when $M=1$.}
\begin{align}\label{posterior2}
p_s(\bm{\vartheta}|\bm{Y}^{(s)})\approx\frac{p(\bm{Y}_{\mathcal{W}_s}|\bm{\vartheta})}{p(\bm{Y}_{\mathcal{W}_s})}\prod_{m=1}^M\tilde{p}_{\Phi_m,\rho(s)}(\vartheta_m),\quad \forall s\in \mathcal{S}.
\end{align}
For brevity, the conditioning on $\bm{Y}^{(\rho(s)-1)}$ is omitted in all windowed conditional PDFs hereafter.
Next, we develop a \emph{variational Bayesian inference} based approach to obtain an explicit and tractable \emph{surrogate posterior PDF} denoted by $q_s(\bm{\vartheta}|\bm{Y}^{(s)})$ that approximates the posterior PDF $p_s(\bm{\vartheta}|\bm{Y}^{(s)})$ with minimum Kullback-Leibler (KL) divergence to $p_s(\bm{\vartheta}|\bm{Y}^{(s)})$. This is equivalent to maximizing the \emph{evidence lower bound (ELBO)} of $q_s(\bm{\vartheta}|\bm{Y}^{(s)})$ given by \cite{bishop2006pattern}
\begin{align}
\mathcal{LB}(q_s)\triangleq&\mathbb{E}_{q_s}\left[\ln p(\bm{Y}^{(s)},\bm{\vartheta})-\ln q_s(\bm{\vartheta}|\bm{Y}^{(s)})\right]
=&\mathbb{E}_{q_s}\!\left[ \ln \frac{p(\bm{Y}_{\mathcal{W}_s}|\bm{\vartheta})\prod_{m=1}^M\tilde{p}_{\Phi_m,\rho(s)}(\vartheta_m)}{q_s(\bm{\vartheta}|\bm{Y}^{(s)})}\right]+\mathrm{const}.\nonumber
\end{align}
Since directly obtaining $q_{s}(\!\bm{\vartheta}|\bm{Y}^{(s)}\!)$ that maximizes $\mathcal{LB}(q_s)$ is not viable, we apply the \emph{mean field approximation} \cite{tzikas2008variational,badiu2017variational} to factorize
\begin{align}\label{mean_field_approximation}
q_{s}(\bm{\vartheta}|\bm{Y}^{(s)})\approx\prod_{m=1}^Mq_{s,m}(\vartheta_m|\bm{Y}^{(s)}),
\end{align}
\vspace{-2mm}
\par\noindent
where $q_{s,m}(\vartheta_m|\bm{Y}^{(s)})$ is the surrogate posterior PDF of $\vartheta_m$ in the $s$-th stage. Then, by iteratively optimizing $q_{s,m}(\vartheta_m|\bm{Y}^{(s)})$ to maximize $\mathcal{LB}(q_s)$ with the surrogate PDFs for other angles fixed at each time, we can transform the original high-dimensional optimization problem on $q_{s}(\bm{\vartheta}|\bm{Y}^{(s)})$ into a series of parallel low-dimensional problems each on $q_{s,m}(\vartheta_m|\bm{Y}^{(s)})$, thereby reducing the complexity.\looseness=-1
\vspace{-5mm}
\subsection{Optimizing Surrogate Posterior PDF for Each Angle}
\vspace{-2mm}
With the surrogate posterior PDFs for other angles being fixed, we obtain $q_{s,m}(\!\vartheta_m|\bm{Y}^{(s)}\!)$ that maximizes $\mathcal{LB}(q_s)$ as follows. Define $W_{s,m}(\vartheta_m)\triangleq\mathbb{E}_{q_{s,\sim m}}[\ln\,(p(\bm{Y}_{\mathcal{W}_s}|\bm{\vartheta}) \tilde{p}_{\bm{\varTheta},\rho(s)}(\bm{\vartheta}))]$ and $\bar{p}_{s,m}(\vartheta_m)\triangleq e^{W_{s,m}(\vartheta_m)}/\int e^{W_{s,m}(\vartheta_m)}d\vartheta_m$ with $\mathbb{E}_{q_{s,\sim m}}[\cdot]$ being the expectation taken over $\prod_{i=1,i\ne m}^M{\!q_{s,i}(\!\vartheta_i|\bm{Y}^{(s)}\!)}$. The ELBO is given as $\mathcal{LB}(q_s)=-\mathcal{D}_{\mathrm{KL}}(q_{s,m}\|\bar{p}_{s,m})+\mathrm{const}$, where $\mathcal{D}_{\mathrm{KL}}(\cdot\|\cdot)$ is the KL divergence. As $\mathcal{D}_{\mathrm{KL}}(q_{s,m}\|\bar{p}_{s,m})$ vanishes if and only if $q_{s,m}( \vartheta_m|\bm{Y}^{(s)})=\bar{p}_{s,m}(\vartheta_m)$, $\mathcal{LB}(q_s)$ can be maximized by setting
 \begin{align}\label{ln_q}
 &\ln{q_{s,m}( \vartheta_m|\bm{Y}^{(s)})}\nonumber
 =&\mathbb{E}_{q_{s,\sim m}}[\ln{(p(\bm{Y}_{\mathcal{W}_s}|\bm{\vartheta}))}]+\ln{\tilde{p}_{\Phi_m,\rho(s)}(\vartheta_m)}+\mathrm{const}.
 \end{align} 
 Since $\ln \tilde{p}_{\Phi_m,\rho(s)}\!(\!\vartheta_m\!)$ is known \emph{a priori}, our remaining task is to find a tractable $\mathbb{E}_{q_{s,\sim m}}\![\ln(p(\!\bm{Y}_{\mathcal{W}_s}|\bm{\vartheta}))]$ for a feasible $q_{s,m}(\vartheta_m|\bm{Y}^{(s)})$.
 To deal with the conditional PDF $p(\bm{Y}_{\mathcal{W}_s}|\bm{\vartheta})$, we introduce an auxiliary PDF $r_s(\bm{\alpha}|\bm{\vartheta})$. Based on Jensen's inequality, we have
 \begin{align}\label{auxiliary_PDF}
 \ln{p(\bm{Y}_{\mathcal{W}_s}|\bm{\vartheta})}\geq \mathbb{E}_{r_s}[\ln{(p(\bm{Y}_{\mathcal{W}_s}|\bm{\eta})p_{\bm{\alpha}}(\bm{\alpha}))}-\ln{r_s(\bm{\alpha}|\bm{\vartheta})}],
 \end{align}
 where the equality holds if and only if $r_s(\bm{\alpha}|\bm{\vartheta})=p(\bm{\alpha}|\bm{Y}_{\mathcal{W}_s},\bm{\vartheta})$. Define $J_s(\bm{\vartheta},\bm{\alpha})\overset{\Delta}{=}\ln{(p(\bm{Y}_{\mathcal{W}_s}|\bm{\eta})p_{\bm{\alpha}}(\bm{\alpha}))}$, which yields $r_s(\bm{\alpha}|\bm{\vartheta})\propto e^{J_s(\bm{\vartheta},\bm{\alpha})}$. Denote $\bm{D}_t=\bm{X}_t^T\otimes \bm{I}_{N_r}$, $\bm{c}(\vartheta_m)=\bm{a}^*(\mathrm{arcsin}\frac{2\vartheta_m}{\pi})\otimes\bm{b}(\mathrm{arcsin}\frac{2\vartheta_m}{\pi})$, and $\bm{E}_t(\bm{\vartheta})=[\bm{D}_t\bm{c}(\vartheta_1),...,\bm{D}_t\bm{c}(\vartheta_M)]$. We have \looseness=-3
 \begin{align}\label{F(theta,alpha)}
 J_s(\bm{\vartheta},\!\bm{\alpha})\!\!=\!\!-\!\!\!\!\sum_{t\in\mathcal{W}_s}\!\!\!\frac{1}{\sigma^2}\!\|\mathrm{vec}(\bm{Y}_t)\!-\!\bm{E}_t(\bm{\vartheta})\bm{\alpha}\|^2\!+\!\ln{\!p_{\bm{\alpha}}(\bm{\alpha})}\!+\!\mathrm{const}.\!\!\!\!
 \end{align}
 Since directly constructing $r_s(\bm{\alpha}|\bm{\vartheta})$ for each possible $\bm{\vartheta}$ is computationally demanding, we average $J_s(\bm{\vartheta},\bm{\alpha})$ over the current surrogate PDF of $\bm{\vartheta}$, yielding $J_s(\bm{\alpha})=\mathbb{E}_{q_s^\prime}[J_s(\bm{\vartheta},\bm{\alpha})]$ and $r_s(\bm{\alpha})\propto e^{J_s(\bm{\alpha})}$, where $q_s^\prime(\bm{\vartheta}|\bm{Y}^{(s)})$ is initialized as the prior PDF at the $\rho(s)$-th stage and set as the surrogate posterior PDF from the previous iteration otherwise. Note that the expectation in $J_s(\bm{\alpha})$ only needs \emph{one-dimensional integration} over each $\vartheta_m$'s since we apply the mean field approximation in (\ref{mean_field_approximation}), which drastically reduces complexity. In the following, we replace $r_s(\bm{\alpha}|\bm{\vartheta})$ with $r_s(\bm{\alpha})$. Let
 \begin{align}\label{alpha_hat_H}
 \bar{\bm{\alpha}}_s=\mathrm{arg}{\max}_{\bm{\alpha}}\ J_s(\bm{\alpha}),\ \bm{H}_{s}=-\nabla^2_{\bm{\alpha}}J_s(\bm{\alpha})|_{\bm{\alpha}=\bar{\bm{\alpha}}_s}.
 \end{align}
 We then have $r_s(\bm{\alpha})\approx\frac{\det(\bm{H}_s)}{\pi^M}
 \exp(-(\bm{\alpha}-\bar{\bm{\alpha}}_s)^{H}\bm{H}_s(\bm{\alpha}-\bar{\bm{\alpha}}_s))$, which is exact with CSCG-distributed $\bm{\alpha}$. Denote $\bm{r}_{t,m}=\mathrm{vec}(\bm{Y}_t)-\sum_{i=1,i\ne m}^M\!\alpha_i\bm{D}_t\bm{c}(\vartheta_i),\forall t\in\mathcal{W}_s$. Based on (\ref{auxiliary_PDF}), we have
 \begin{align}\label{ln_q_s_m}
 &\mathbb{E}_{q_{s,\sim m}}\![\ln{(p(\bm{Y}_{\mathcal{W}_s}|\bm{\vartheta}))}]\!=\!\!\!\sum_{t\in\mathcal{W}_s}\!\!\!\frac{1}{\sigma^2}\!\Big[\!\!-\!\mathbb{E}_{q_{s,\sim m},r_s}[|\alpha_m|^2\|\bm{D}_t\bm{c}(\vartheta_m)\|^2]\nonumber[-2mm]
 &+2\mathfrak{Re}\{\mathbb{E}_{q_{s,\sim m},r_s}[\alpha_m\bm{r}_{t,m}^H\bm{D}_t\bm{c}(\vartheta_m)]\}\Big]+\mathrm{const}.
 \end{align} 

 Based on this, we can obtain a \emph{closed-form} $q_{s,m}(\! \vartheta_m|\bm{Y}^{(\!s\!)}\!)$ from (\ref{ln_q}) and (\ref{ln_q_s_m}). Denote $\hat{\bm{\vartheta}}^\prime_s$ as the estimate of $\bm{\vartheta}$ from the previous iteration, $\bm{\zeta}_{s,m}\!\!=\!\!\sum_{t\in\mathcal{W}_s}\!\bm{\zeta}_{s,m,t}$, and $\bm{\zeta}_{s,m,t}\!=\!\frac{2}{\sigma^2}\!(\!-\!\!\sum_{i=1,i\ne m}^M[\bm{H}_{s}^{-1}]_{i,m}\times\bm{D}_t^H\!\bm{D}_t\bm{c}(\!\hat{\vartheta}^\prime_{s,i})\!+\!\bm{D}_t^H\!\big(\!\mathrm{vec}(\bm{Y}_t\!)\!-\!\sum_{i=1,i\ne m}^M\!\bar{\alpha}_{s,i}\!\!\bm{D}_t\bm{c}(\hat{\vartheta}^\prime_{s,i}\!)\big)\bar{\alpha}_{s,m}^*)$. Define $\bm{d}(\!\vartheta_m\!)\!\!\in\!\!\mathbb{C}^{(2N_t\!+\!2N_r-3)\times 1}$ with $d_i(\vartheta_m)\!\!\overset{\Delta}{=}\!\!e^{-j(2N_t+2N_r-2-2i)\vartheta_m}$. Moreover, define $\bm{\gamma}_t^{\prime}\!\in\!\mathbb{C}^{(2N_t+2N_r-3)\times 1}$ that satisfies $\|\bm{D}_t\bm{c}(\vartheta_m)\|^2\!=\!\bm{\gamma}_t^{\prime H}\bm{d}(\vartheta_m)$. We then have
 \begin{align}\label{q_vartheta_y}
 &\ln{q_{s,m}( \vartheta_m|\bm{Y}^{(s)})}\nonumber[-3mm]
 =&\ln{\tilde{p}_{\Phi_m,\rho(s)}(\vartheta_m)}+\sum_{p=1}^{N_tN_r}|\zeta_{s,m,p}|\cos(c^{(p)}\vartheta_m-\mu_{s,m,p})\nonumber[-4mm]
 &+\sum_{q=1}^{2N_t+2N_r-3}|\gamma_{s,m,q}|\cos(d^{(q)}\vartheta_m-\mu^\prime_{s,m,q})+\mathrm{const},
 \end{align}
 \vspace{-3mm}
 \par\noindent
 where $\bm{\gamma}_{s,m}=\sum_{t\in\mathcal{W}_s}\bm{\gamma}_{s,m,t}$ with $\bm{\gamma}_{s,m,t}=-\frac{1}{\sigma^2}([\bm{H}_{s}^{-1}]_{m,m}+|\bar{\alpha}_{s,m}|^2)\bm{\gamma}_t^\prime$, $c^{(p)}\!\!=\!\!-(-N_t\!+\!N_r\!+\!2\lfloor\! \frac{p-1}{N_r}\!\rfloor\!-\!2((p\!-\!1) \mathrm{mod}\, N_r\!))$, $\mu_{s,m,p}=\!\!\mathrm{arg}(\zeta_{s,m,p})$, $d^{(q)}\!\!=\!\!-(2N_t\!\!+\!\!2N_r\!-\!2\!\!-\!\!2q)$, and $\mu^\prime_{s,m,q}\!\!=\!\!\mathrm{arg}(\gamma_{s,m,q})$.
 Finally, the pseudo angle $\hat{\vartheta}_{s,m}$ can be sensed via either Newton's method to maximize (\ref{q_vartheta_y}) in marginal MAP or integration of $\mathbb{E}_{q_{s,m}}[\vartheta_m]$ in MMSE, which is fed into the following iterations for obtaining the surrogate posterior PDF of other angles. By iteratively updating all $q_{s,m}(\vartheta_m|\bm{Y}^{(s)})$'s until convergence, the overall surrogate posterior PDF of $\bm{\vartheta}$ is obtained via (\ref{q_vartheta_y}), which is used for the Bayesian beamforming and Bayesian sensing in the $(s+1)$-th stage.

\vspace{-5mm}
\subsection{Complexity with Proposed Posterior PDF Characterization}
\vspace{-2mm}
The complexity of the proposed characterization approach mainly lies in the calculation of $\bar{\bm{\alpha}}_s$, $\bm{H}_{s}$, and $\bm{\vartheta}$. Let $I_{\bm{\alpha}}$, $I_{\bm{\vartheta}}$, and $I_\mathrm{iter}$ denote the maximum numbers of Newton iterations for updating $\bar{\bm{\alpha}}_s$ and each $\vartheta_{m}$, and the maximum number of outer iterations of the proposed approach, respectively. Denote $\mathrm{card}(\cdot)$ as the cardinality of a set. The complexities for Bayesian beamforming and Bayesian sensing with our proposed posterior PDF characterization are summarized in Table \ref{Table_complexity}. Note that all complexities are \emph{polynomial} in the number of targets, $M$, which is much lower compared to its \emph{exponential} counterpart with numerical calculation.
\vspace{-4mm}
\section{Numerical Results}\label{section_numerical_results}
\vspace{-3mm}
This section presents numerical results. We set $N_t=8$, $N_r=10$, $L=100$, $\sigma^2=-90$ dBm, and consider the Gaussian mixture initial prior PDF model for each $\theta_m$ as adopted in \cite{xu2023mimo1}. We further set $\alpha_m\sim\!\mathcal{CN}(0,2\times 10^{-12})$ and consider the marginal MAP estimator in our framework. Fig. \ref{convergence_behavior} shows the convergence behavior of our proposed approach in characterizing the posterior PDF under $S=1$ and different $M$, where $\varsigma_{1,i}\!\!=\!\!\|\hat{\bm{\vartheta}}^{(i)}_1\!-\!\hat{\bm{\vartheta}}^{(i\!-\!1)}_1\!\|/\|\hat{\bm{\vartheta}}^{(i\!-\!1)}_1\!\|$ denotes the relative difference of angle estimates over iterations. Fast convergence is observed in 15 iterations under convergence threshold $10^{-6}$. 
Then, we compare our proposed framework with our proposed posterior PDF characterization approach versus the following benchmark schemes, which adopt the same Bayesian beamforming but different estimation methods: 
\begin{enumerate}
\item {\bf{MUltiple SIgnal Classification (MUSIC) \cite{schmidt1986multiple}}}: The targets' angles are estimated by identifying peaks in the spatial spectrum and associated to the targets' indices according to their prior PDFs; 
\item {\bf{Estimate of Signal Parameters via Rotational Invariance Technique (ESPRIT) \cite{roy1989esprit}}}: The targets' angles are estimated via subspace-based ESPRIT, which is also used as the initialization of the first iteration in the first stage of our framework; 
\item {\bf{VALSE} \cite{badiu2017variational}}: We apply the VALSE algorithm to jointly estimate $\bm{\theta}$ and $\bm{\alpha}$ under our model where $\bm{\alpha}$ is a nuisance parameter vector; 
\item {\bf{Marginal MAP (with numerically calculated posterior PDF)}}; 
\item {\bf{MMSE (with numerically calculated posterior PDF)}}.
\end{enumerate}
