\hline
0 & 0.08540 & 0.09656 & 0.13203 
1 & 0.17253 & 0.13865 & 0.06056 
2 & 0.17253 & 0.17585 & 0.12940 
3 & 0.07466 & 0.08866 & 0.12940 
4 & 0.02405 & 0.03099 & 0.06838 
5 & 0.00773 & 0.01019 & 0.02736
\end{array}
