\section{A. Stage Scoring Definitions and Equations}
\paragraph{Notation.}
Let $\mathcal{Y}$ denote the task label space, $H^{(0)}$ the initial hypothesis set, $\mathcal{E}^*$ the accumulated image-grounded evidence, $H^*$ the final verified hypothesis set, $\mathcal{V}$ the controlled clinical vocabulary, $\Gamma$ the natural-language-to-first-order-logic parser, and $\Phi=\Gamma(H)$ the corresponding logical premises. $\hat{y}$ denotes the predicted label and $\hat{h}$ the hypothesis cited in support of that prediction.
\paragraph{Score $s_1$.} S1 is scored by a three-item rubric averaged to
$[0,1]$:
\begin{align}
s_1 &= \tfrac{1}{2}\Bigl(\underbrace{\mathbbm{1}\!\left[H^{(0)}\neq\varnothing\right]}_{\text{non-empty}}
+ \underbrace{\frac{\sum_{y\in \mathcal{Y}} \mathbbm{1} \left[{\exists h\in H^{(0)}, x \rightarrow^{h} y\ }\right]}{|\mathcal{Y}|}}_{\text{per-label coverage}} \Bigr)
\end{align}
where the first term indicates that the hypotheses set generated has at least 1 hypothesis, and the 2nd term indicates that there is at least one hypothesis per label. The best agentic score ($s_1 = 1$) is obtained when both conditions hold. 
\paragraph{Score $s_2$.} Let $\mathcal{F}(e_t)$ be the findings cited by the
agent and $\mathcal{F}^{\star}(x_t)$ the label-relevant findings marked present
by expert annotation of the (few) support images. We report precision and
recall separately and combine them, weighting fidelity above completeness since
a fabricated finding is the clinical dealbreaker:
\begin{align}
\mathrm{Prec} &= \frac{|\mathcal{F}(e_t)\cap\mathcal{F}^{\star}(x_t)|}{|\mathcal{F}(e_t)|}, \quad
\mathrm{Rec} = \frac{|\mathcal{F}(e_t)\cap\mathcal{F}^{\star}(x_t)|}{|\mathcal{F}^{\star}(x_t)|}, 
\mathrm{Obs} &= \frac{|\{c\in e_t:\, c\in\mathcal{V}\}|}{|e_t|}, 
s_2 &= 0.5 \mathrm{Prec}+0.4\mathrm{Rec}+0.1\mathrm{Obs}
\end{align}
where $\mathrm{Obs}$ (observability) is the fraction of claims referencing a
concrete vocabulary finding rather than an abstract inference. 
\paragraph{Score $s_3$.} Refinement is scored by the improvement in prediction accuracy of downstream task before and after the refinement step, when compared against the ground truth label, for a smaller validation set of 50 observations. 
\begin{align}
s_3 = \text{Acc}_{H^{(\mathcal{E}^*)}} - \text{Acc}_{H^{(0)}}
\end{align}
\paragraph{Score $s_4$.} We score the translation fidelity of the LLM parser using a Natural Language Inference (NLI) model (DeBERTa-v3-large) ~\cite{he2021deberta}. First, we compute the natural language hypothesis back from the first order logic:
\begin{equation}
\tilde{H^{*}} = \Gamma^{-1}(\Phi)
\end{equation}
We then test whether $H^{*}$ and $\hat{H^{*}}$ mutually entail one another (each statement implies the other). The NLI gives us the entailment probability (probability of one statement implying the other) and we get the score as the min of 2 probabilities. 
\begin{align}
s_4 = \min\left[P_{\mathrm{e}}\!\left(H^* \rightarrow \tilde{H}^*\right),
P_{\mathrm{e}}\!\left(\tilde{H}^* \rightarrow H^* \right)\right] 
\end{align}
This ensures that the 2 statements are equivalent and the first order logic statement was correct. 
\paragraph{S5: Final diagnosis.}
The process score checks whether the prediction lies in the permitted label space and whether the model cites a hypothesis from the verified set as support:
\begin{equation}
s_5 = \frac{1}{2}\left[
\ind(\hat{y}\in\mathcal{Y})+\ind(\hat{h}\in H^*)
\right].
\label{eq:s5}
\end{equation}
\paragraph{Task score.}
Diagnostic outcome quality is measured separately from process quality as the mean of accuracy, F1 score, precision, and recall on the held-out query set:
\begin{equation}
\mathrm{TASK}=\frac{1}{4}\left[
\mathrm{Acc}+\mathrm{F1}+\mathrm{Prec}+\mathrm{Rec}
\right].
\label{eq:task}
\end{equation}
\paragraph{Workflow-level aggregation.}
The five stage scores are combined using the weights reported in the main manuscript, with the greatest weight assigned to image grounding:
\begin{align}
\mathrm{AGENTIC} &= \sum_{k=1}^{5}w_k s_k,
\mathrm{OVERALL} &= \frac{1}{2}\mathrm{AGENTIC}+\frac{1}{2}\mathrm{TASK}.
\end{align}
where $(w_1,\ldots,w_5) = (0.20,0.30,0.20,0.20,0.10)$
