\section{Gradient Derivation for RIS Phase Optimization in Stage I}
\label{app:gradient_sensing}
Since $g(\boldsymbol{\phi}_s)$ is a real-valued function with respect to
the complex variable $\boldsymbol{\phi}_s$, the Euclidean gradient is
obtained according to Wirtinger calculus as
\begin{equation}
	\nabla g(\boldsymbol{\phi}_s)
	=
	-2
	(c_0+\boldsymbol{\phi}_s^T\mathbf v)
	\mathbf v^{*}.
	\label{eq:app_euclidean_gradient}
\end{equation}
The feasible set
$
\mathcal M
=
\{
\boldsymbol{\phi}_s\in\mathbb C^{N_R}
\mid
|\phi_{s,n}|=1,\forall n
\}
$
forms a complex circle product manifold.
The tangent space at
$\boldsymbol{\phi}_s$ is given by
\begin{equation}
	T_{\boldsymbol{\phi}_s}\mathcal M
	=
	\{
	\mathbf d\in\mathbb C^{N_R}
	\mid
	\Re(\overline{\phi}_{s,n}d_n)=0,\forall n
	\}.
\end{equation}
The Euclidean gradient is projected onto the tangent space to obtain the
Riemannian gradient
\begin{equation}
	\operatorname{grad}
	g(\boldsymbol{\phi}_s)
	=
	\operatorname{Proj}_{\boldsymbol{\phi}_s}
	(
	\nabla g(\boldsymbol{\phi}_s)
	),
\end{equation}
where the projection operator is defined as
\begin{equation}
	\operatorname{Proj}_{\boldsymbol{\phi}_s}
	(\mathbf u)
	=
	\mathbf u
	-
	\Re
	(
	\overline{\boldsymbol{\phi}}_s
	\odot
	\mathbf u
	)
	\odot
	\boldsymbol{\phi}_s .
	\label{eq:app_projection}
\end{equation}
To update the manifold point, the retraction operation is adopted
\begin{equation}
	R_{\boldsymbol{\phi}_s}(\mathbf d)
	=
	\frac{
		\boldsymbol{\phi}_s+\mathbf d
	}
	{
		|
		\boldsymbol{\phi}_s+\mathbf d
		|
	},
	\label{eq:app_retraction}
\end{equation}
where the division is performed element-wise.
The vector transport between two tangent spaces is implemented by
\begin{equation}
	\mathcal T_{\boldsymbol{\phi}_s\rightarrow\boldsymbol{\psi}_s}
	(\mathbf d)
	=
	\operatorname{Proj}_{\boldsymbol{\psi}_s}(\mathbf d).
	\label{eq:app_transport}
\end{equation}
Based on the Riemannian gradient, the conjugate search direction is
updated using the Hestenes-Stiefel (HS) formula. Specifically,
$\beta_j=\frac{\left\langle\mathbf g^{(j)}-\mathbf g_{\rm old},\mathbf g^{(j)}\right\rangle}{\left\langle\mathbf g^{(j)}-\mathbf g_{\rm old},
\mathbf d_{\rm old}\right\rangle}$,
where the inner product is defined as
$
	\langle\mathbf a,\mathbf b\rangle
	=
	\Re(\mathbf a^H\mathbf b)
$.
To improve numerical stability, the HS+ modification is adopted: $\beta_j=\max(\beta_j,0)$.
The search direction is then updated as
\begin{equation}
	\mathbf d^{(j)}
	=
	-\mathbf g^{(j)}
	+
	\beta_j\mathbf d_{\rm old}.
\end{equation}
The step size $\alpha_j$ is determined by the Armijo backtracking line
search. Starting from an initial value, it is reduced by a factor
$\tau\in(0,1)$ until
\begin{equation}
	g
	\left(
	R_{\boldsymbol{\phi}_s^{(j)}}
	(\alpha_j\mathbf d^{(j)})
	\right)
	\leq
	g(\boldsymbol{\phi}_s^{(j)})
	+
	c\alpha_j
	\langle
	\mathbf g^{(j)},
	\mathbf d^{(j)}
	\rangle ,
\end{equation}
where $c\in(0,1)$ is the Armijo parameter.
\section{Gradient Derivation for RIS Phase Optimization in Stage II}
\label{app:gradient}
For fixed $\mathbf W$, the equivalent Eve channel vector can be
written as
\[
\mathbf h_e(\mathbf p_e;\boldsymbol{\Phi}_c)
=
\mathbf h_{be}(\mathbf p_e)
+
(\mathbf H_{br}^{\mathcal R})^H
\boldsymbol{\Phi}_c^H
\mathbf h_{re}^{\mathcal R}(\mathbf p_e).
\]
Define
$
\mathbf D_n
\triangleq
\frac{\partial\mathbf h_0}{\partial\phi_{c,n}^{*}}
$, $
\mathbf G_n
\triangleq
\frac{\partial\mathbf J_h}{\partial\phi_{c,n}^{*}}
$.
Then, the derivatives of the nominal Eve channel and its
Jacobian with respect to $\phi_{c,n}^{*}$ are given by
$
	\mathbf D_n
	=
	(\mathbf H_{br}^{\mathcal R})^H
	\mathbf E_{nn}\mathbf h_{re}^{\mathcal R}$,
$	\mathbf G_n
	=
	(\mathbf H_{br}^{\mathcal R})^H
	\mathbf E_{nn}
	\frac{\partial\mathbf h_{re}^{\mathcal R}}
	{\partial\mathbf p_e^T}
$,
where $\mathbf E_{nn}$ denotes the elementary matrix whose
only nonzero entry is the $(n,n)$-th entry.
Let
$\widetilde{\mathbf W}=\mathbf W/\sigma_e^2$.
Since $\mathbf W$ is fixed in the RIS phase-shift subproblem,
the derivatives of the quadratic-form coefficients
$\mathbf A=\Re(\mathbf J_h^H\widetilde{\mathbf W}\mathbf J_h)$,
$\mathbf b=\Re(\mathbf J_h^H\widetilde{\mathbf W}\mathbf h_0)$,
and $c=\mathbf h_0^H\widetilde{\mathbf W}\mathbf h_0$
are obtained using Wirtinger calculus as
\begin{equation}
	\frac{\partial\mathbf A}{\partial\phi_{c,n}^{*}}
	=
	\frac{1}{2}
	\left(
	\mathbf J_h^H\widetilde{\mathbf W}\mathbf G_n
	+
	\mathbf G_n^T\widetilde{\mathbf W}^{*}\mathbf J_h^{*}
	\right).
\end{equation}
\begin{equation}
	\frac{\partial\mathbf b}{\partial\phi_{c,n}^{*}}
	=
	\frac{1}{2}
	\left(
	\mathbf J_h^H\widetilde{\mathbf W}\mathbf D_n
	+
	\mathbf G_n^T\widetilde{\mathbf W}^{*}\mathbf h_0^{*}
	\right).
\end{equation}
\begin{equation}
	\frac{\partial c}{\partial\phi_{c,n}^{*}}
	=
	\mathbf h_0^H\widetilde{\mathbf W}\mathbf D_n.
\end{equation}
Since $\bar{\gamma}_e(\eta,\Gamma)$ and $\mathbf M$ are
independent of $\boldsymbol{\phi}_c$, the derivative of the
LMI matrix with respect to $\phi_{c,n}^{*}$ is
\begin{equation}
	\frac{\partial\mathbf S}{\partial\phi_{c,n}^{*}}
	=
	\begin{bmatrix}
		-\dfrac{\partial\mathbf A}{\partial\phi_{c,n}^{*}}
		&
		-\dfrac{\partial\mathbf b}{\partial\phi_{c,n}^{*}}
		[6pt]
		-\left(\dfrac{\partial\mathbf b}
		{\partial\phi_{c,n}^{*}}\right)^T
		&
		-\dfrac{\partial c}{\partial\phi_{c,n}^{*}}
	\end{bmatrix}.
\end{equation}
For $\mathbf S\succ0$, the Wirtinger derivative of the
logarithmic barrier function
$F_\mu(\boldsymbol{\phi}_c)=\mu\log\det\mathbf S$
is given by
\begin{equation}
	\frac{\partial F_\mu}{\partial\phi_{c,n}^{*}}
	=
	\mu\operatorname{tr}
	\left(
	\mathbf S^{-1}
	\frac{\partial\mathbf S}{\partial\phi_{c,n}^{*}}
	\right).
\end{equation}
Collecting the derivatives of all RIS elements yields the
Euclidean gradient
\begin{equation}
	\nabla_{\boldsymbol{\phi}_c^*} F_\mu = \mu \left[ \operatorname{tr}\left( \mathbf S^{-1} \frac{\partial\mathbf S}{\partial\phi_{c,1}^{*}} \right), \ldots, \operatorname{tr}\left( \mathbf S^{-1} \frac{\partial\mathbf S}{\partial\phi_{c,N_R}^{*}} \right) \right]^T.
\end{equation}
Under the real inner product
$\langle\mathbf u,\mathbf v\rangle=\Re(\mathbf u^H\mathbf v)$,
the Euclidean gradient is
$\mathbf g_E=2\nabla_{\boldsymbol{\phi}_c^{*}}F_\mu$.
