\title{UAV Rotatable Antenna under Rotation Delay}
\author{Yinmei~Xie,~\IEEEmembership{Graduate Student Member,~IEEE}, Chiya~Zhang,~\IEEEmembership{Member,~IEEE},
Chunlong~He,~\IEEEmembership{Member,~IEEE},
Weizheng~Zhang,~\IEEEmembership{Member,~IEEE},
