\section{Proof of Theorem~\ref{thm:single_optimal_rotation}}
\label{app:proof_theorem1}
To prove the strict concavity of $\bar R_{\mathrm{FF}}(\delta)$, define
 $\ell(\delta)
 \triangleq
 \ln\!\left[
 1+C\cos^{2p}(\alpha-\delta)
 \right].$
Then,
 $\bar R_{\mathrm{FF}}(\delta)
 =
 \frac{B}{\ln 2}
 A(\delta)\ell(\delta).$
Over the feasible interval,
$0\leq\alpha-\delta<\pi/2$ since
$\bar{\delta}\leq\alpha<\pi/2$.
Differentiating $\ell(\delta)$ gives
\begin{equation}
	\ell'(\delta)
	=
	\frac{
		2pC\cos^{2p}(\alpha-\delta)
		\tan(\alpha-\delta)
	}{
		1+C\cos^{2p}(\alpha-\delta)
	}.
	\label{eq:appA_l_first}
\end{equation}
Thus, $\ell'(\delta)\geq0$, with
$\ell'(\delta)>0$ whenever $\delta<\alpha$.
The second derivative is
\begin{align}
	\ell''(\delta)
	={}&
	-
	\frac{
		2pC\cos^{2p}(\alpha-\delta)
	}{
		\left[
		1+C\cos^{2p}(\alpha-\delta)
		\right]^2
		\cos^2(\alpha-\delta)
	}
	\nonumber
	&\times
	\left[
		1
		+
		C\cos^{2p}(\alpha-\delta)
		-
		2p\sin^2(\alpha-\delta)
	\right].
	\label{eq:appA_l_second}
\end{align}
Under condition~\eqref{eq:concavity_condition},
it follows that $\ell''(\delta)\leq0$.
Moreover,
$A'(\delta)=-1/(\omega T_s)$ and $A''(\delta)=0$.
Therefore,
\begin{equation}
	\bar{R}_{\mathrm{FF}}''(\delta)
	=
	\frac{B}{\ln 2}
	\left[
	A(\delta)\ell''(\delta)
	-
	\frac{2}{\omega T_s}\ell'(\delta)
	\right].
	\label{eq:appA_rate_second}
\end{equation}
Since
$0\leq\delta\leq\bar{\delta}\leq\delta_{\max}\leq\omega T_s$,
we have $A(\delta)\geq0$.
Together with $\ell'(\delta)>0$ for $\delta<\alpha$ and
$\ell''(\delta)\leq0$, \eqref{eq:appA_rate_second} gives
$\bar{R}_{\mathrm{FF}}''(\delta)<0$ for $\delta<\alpha$.
Hence, if $\bar{\delta}<\alpha$,
$\bar{R}_{\mathrm{FF}}(\delta)$ is strictly concave over
$[0,\bar{\delta}]$.
If $\bar{\delta}=\alpha$, the same result holds on
$[0,\alpha)$, and continuity at the endpoint extends the
strict concavity to $[0,\alpha]$.
Thus, $\bar{R}_{\mathrm{FF}}(\delta)$ is strictly concave over
$[0,\bar{\delta}]$ in either case, and problem~\eqref{prob:far_field}
has a unique global optimum.
The location of the optimum follows directly from the strict monotonicity of
$\bar{R}_{\mathrm{FF}}'(\delta)$.
If $\bar{R}_{\mathrm{FF}}'(0)\leq0$, then
$\delta^\star=0$.
If $\bar{R}_{\mathrm{FF}}'(\bar{\delta})\geq0$, then
$\delta^\star=\bar{\delta}$.
Otherwise,
$\bar{R}_{\mathrm{FF}}'(0)>0$ and
$\bar{R}_{\mathrm{FF}}'(\bar{\delta})<0$,
so there exists a unique
$\delta_0\in(0,\bar{\delta})$
such that
$\bar{R}_{\mathrm{FF}}'(\delta_0)=0$.
Hence, $\delta^\star=\delta_0$.
Combining the three cases gives
\eqref{eq:optimal_delta_exact}, which completes the proof.
\section{Proof of Theorem~\ref{thm:closed_form_rotation}}
\label{app:proof_theorem2}
Define
$\psi(x)\triangleq\ln\!\left(1+C\cos^{2p}x\right)$.
Since $\psi(x)$ is an even function,
$\psi(0)=\ln(1+C)$,
$\psi'(0)=0$, and
$\psi''(0)=-\frac{2Cp}{1+C}$.
Its second-order Taylor expansion about $x=0$ is therefore
\begin{equation}
	\psi(x)
	=
	\ln(1+C)
	-
	\frac{Cp}{1+C}x^2
	+
	\mathcal O(x^4).
	\label{eq:appB_taylor}
\end{equation}
Retaining terms up to second order and substituting
\eqref{eq:appB_taylor} into \eqref{eq:rate_x} gives
\begin{equation}
	\widetilde{\mathcal R}(x)
	=
	\frac{B}{\omega T_s\ln2}
	(a+x)
	\left[
	\ln(1+C)
	-
	\frac{Cp}{1+C}x^2
	\right].
	\label{eq:appB_approx_rate}
\end{equation}
For notational simplicity, define
$\kappa\triangleq\frac{Cp}{1+C}$ and
$L\triangleq\ln(1+C)$.
Since $C>0$ and $p>0$, both $\kappa$ and $L$ are positive.
Then,
\begin{equation}
	\widetilde{\mathcal R}(x)
	=
	\frac{B}{\omega T_s\ln2}
	(a+x)(L-\kappa x^2).
	\label{eq:appB_compact_rate}
\end{equation}
Its first and second derivatives are, respectively,
\begin{align}
	\widetilde{\mathcal R}'(x)
	&=
	\frac{B}{\omega T_s\ln2}
	\left(
	L-2a\kappa x-3\kappa x^2
	\right),
	\label{eq:appB_first_derivative}

	\widetilde{\mathcal R}''(x)
	&=
	-\frac{2B\kappa}{\omega T_s\ln2}
	(a+3x).
	\label{eq:appB_second_derivative}
\end{align}
Since $a>0$, $\kappa>0$, and $x\geq0$ over the feasible interval,
\eqref{eq:appB_second_derivative} gives
$\widetilde{\mathcal R}''(x)<0$.
Hence, $\widetilde{\mathcal R}(x)$ is strictly concave, and its unique stationary point is the unconstrained maximizer.
Setting $\widetilde{\mathcal R}'(x)=0$ gives
\begin{equation}
	3\kappa x^2
	+
	2a\kappa x
	-
	L
	=
	0.
	\label{eq:appB_stationary}
\end{equation}
The two roots are
\begin{equation}
	x_{\pm}
	=
	\frac{
		-a
		\pm
		\sqrt{
 a^2+\frac{3L}{\kappa}
		}
	}{3}.
	\label{eq:appB_roots}
\end{equation}
Since $L>0$ and $\kappa>0$,
$\sqrt{a^2+3L/\kappa}>a$.
Thus, $x_-<0$ and $x_+>0$, so the unique nonnegative stationary point is
\begin{equation}
	x_{\mathrm{cf}}
	=
	\frac{
		\sqrt{
 a^2+\frac{3L}{\kappa}
		}
		-a
	}{3}.
	\label{eq:appB_xcf}
\end{equation}
Substituting $L=\ln(1+C)$ and
$\kappa=Cp/(1+C)$ gives \eqref{eq:x_cf}.
Since $\widetilde{\mathcal R}(x)$ is strictly concave, $x_{\mathrm{cf}}$ is optimal if it lies in the feasible interval
$[\alpha-\bar{\delta},\alpha]$; otherwise, the optimum is attained at the corresponding boundary point.
Using $\delta=\alpha-x$, the resulting rotation budget is given by
\eqref{eq:delta_cf}, which completes the proof.
